// Isolated review data, generated by the real achievement rules. No backend access.
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const cp = require('node:child_process');
const rules = require('../../../functions/seasonalAchievements');
const root = path.resolve(__dirname, '../../..');
const nowMs = Date.parse('2026-09-13T12:00:00Z');
const capacity = { goldPerHour: 24000, troopPerHour: 12000 };
const fresh = () => rules.createSeasonalAchievementState({ uid:'design-preview', worldId:'design-preview', resetGeneration:'design-preview', nowMs });
let mixed = fresh();
function apply(event, count = 1) {
  for (let i=0; i<count; i++) mixed = rules.applySeasonalAchievementEvent(mixed, { ...event, occurredAtMs:nowMs-3600000 }, capacity, nowMs).state;
}
apply({ type:'BATTLE_RESOLVED', targetCategory:'player_city', success:true, cityCaptured:true }, 100);
apply({ type:'ATTACK_LAUNCHED', targetCategory:'player_city', committedTroops:5000 }, 100);
apply({ type:'CAMP_CAPTURED', targetCategory:'camp', success:true, campCaptured:true }, 45);
apply({ type:'CITY_UPGRADED', levelsGained:420 });
for (const strongholdType of ['gold','training','speed']) apply({ type:'STRONGHOLD_CAPTURED', strongholdType });
apply({ type:'BATTLE_RESOLVED', targetCategory:'stronghold', committedTroops:8000 }, 14);
apply({ type:'CITADEL_CAPTURED', attackerPlayerId:'design-preview' });
apply({ type:'LONG_REIGN_PROGRESS', heldMs:5.75*3600000 });
apply({ type:'CLAN_GIFT_SENT', clanGiftSent:true }, 8);
apply({ type:'DAILY_MISSIONS_COMPLETED', count:31 });
for (let day=1;day<=7;day++) apply({ type:'DAILY_ALL_COMPLETED', dateKey:`2026-09-${String(day).padStart(2,'0')}` });
mixed.achievements.forEach(a => { if(a.completedAtMs && !['conqueror_iii','warlord','builder_ii'].includes(a.id)) a.claimedAtMs=nowMs-1800000; });
mixed.claimedCount=mixed.achievements.filter(a=>a.claimedAtMs).length;
const game = fs.readFileSync(path.join(root,'game.js'),'utf8');
const noteSource = game.match(/function getSeasonalAchievementRequirementNote\(entry = \{\}\) \{([\s\S]*?)\n\}/);
if(!noteSource) throw Error('Current achievement requirement notes not found');
const requirementNote = vm.runInNewContext(`(function(entry={}) {${noteSource[1]}\n})`);
const notes = Object.fromEntries(mixed.achievements.map(a=>[a.metric,requirementNote(a)]));
const items = {};
for(const id of ['swift_march_order','recall_horn','shield_12h']) {
  const source=game.slice(game.indexOf(`id: "${id}"`));
  items[id]={ label:source.match(/label: "([^"]+)"/)[1], art:source.match(/icon: "([^"]+)"/)[1] };
}
const payload={ mixed, fresh:fresh(), capacity, notes, items, nowMs, categories:rules.CATEGORY_LABELS,
  capturedFrom:cp.execFileSync('git',['rev-parse','origin/main'],{cwd:root,encoding:'utf8'}).trim() };
fs.writeFileSync(path.join(__dirname,'samples.js'),'/* Synthetic examples generated from current achievement definitions and events. */\nwindow.AchievementReviewSamples = '+JSON.stringify(payload,null,2)+';\n');
console.log(`Captured ${mixed.achievements.length} achievements, ${Object.keys(payload.categories).length} categories, and ${Object.keys(items).length} item rewards from current source.`);
